\begin{definition}[Quantum state]
A \emph{quantum state} on a system of $m$ elementary states is an $m \times m$ complex Hermitian positive semidefinite matrix $\rho$ with $\operatorname{Tr} \rho = 1$. It is \emph{pure} if $\rho = w w^{*}$ for a unit vector $w \in \mathbb{C}^{m}$.
\end{definition}

\begin{definition}[Measurement operator]
A \emph{measurement operator} on a system of $m$ elementary states is an $m \times m$ complex Hermitian matrix $\mathcal{M}$ with $0 \preceq \mathcal{M} \preceq I$. The probability that $\mathcal{M}$ accepts a state $\rho$ is $\operatorname{Tr}(\rho \mathcal{M})$.
\end{definition}

\begin{definition}[Separable state]
Take $m = n^{2}$ and identify $[m]$ with $[n] \times [n]$ as above. A pure state $\rho = w w^{*}$ on $\mathbb{C}^{m}$ is \emph{separable} if the vector $w \in \mathbb{C}^{m}$, viewed as an $n \times n$ matrix, equals $u v^{*}$ for some $u, v \in \mathbb{C}^{n}$. A general state $\rho$ is \emph{separable} if it is a convex combination of separable pure states, that is $\rho = \mathbb{E}\,(u v^{*})(u v^{*})^{*}$ for some distribution over pairs of unit vectors $u, v \in \mathbb{C}^{n}$. A state that is not separable is \emph{entangled}.
\end{definition}

\begin{definition}[The promise problem $\mathrm{BSS}_{c,s}$]
Let $0 \le s < c \le 1$. An instance of $\mathrm{BSS}_{c,s}$ is an $n^{2} \times n^{2}$ measurement operator $\mathcal{M}$. It is a \textsc{yes} instance if there exists a separable state $\rho$ on $\mathbb{C}^{n^{2}}$ with $\operatorname{Tr}(\rho \mathcal{M}) \ge c$, and a \textsc{no} instance if every separable state $\rho$ on $\mathbb{C}^{n^{2}}$ satisfies $\operatorname{Tr}(\rho \mathcal{M}) \le s$. Instances that are neither carry no promise.
\end{definition}
